import React, { useEffect, useState } from "react";
import api from "../services/api";
import MonitoringWidget from "../components/MonitoringWidget";
import MLWidget from "../components/MLWidget";

const AdminDashboard = () => {
  const [metrics, setMetrics] = useState([]);
  const [darkMode, setDarkMode] = useState(false);

  useEffect(() => {
    api.get("/api/agent/metrics")
      .then((response) => {
        setMetrics(response.data);
      })
      .catch((error) => {
        console.error("Error fetching metrics:", error);
      });
  }, []);

  // Mock server logs and error rates
  const serverLogs = [
    "Server started successfully",
    "Database connection established",
    "API response time: 120ms",
    "Warning: High memory usage detected",
  ];

  const errorRate = "2.5%"; // Example error rate

  const handleToggleDarkMode = () => {
    setDarkMode((prev) => !prev);
    document.body.style.backgroundColor = darkMode ? "#fff" : "#1e293b";
    document.body.style.color = darkMode ? "#000" : "#fff";
  };

  const handleAutomateResolution = () => {
    alert("Automated resolution triggered!");
    // Add API call or logic for triggering automation
  };

  return (
    <div
      style={{
        padding: "2rem",
        backgroundColor: darkMode ? "#1e293b" : "#f8fafc",
        color: darkMode ? "#f8fafc" : "#1e293b",
        minHeight: "100vh",
      }}
    >
      {/* Navbar */}
      <div
        style={{
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          flexDirection: "column",
          marginBottom: "2rem",
        }}
      >
        <h1 style={{ margin: 0, fontSize: "2rem" }}>Admin Dashboard</h1>
        <button
          onClick={handleToggleDarkMode}
          style={{
            marginTop: "1rem",
            padding: "0.5rem 1rem",
            backgroundColor: darkMode ? "#f1c40f" : "#4caf50",
            color: "#fff",
            border: "none",
            borderRadius: "5px",
            cursor: "pointer",
          }}
        >
          Toggle {darkMode ? "Light" : "Dark"} Mode
        </button>
      </div>

      {/* Server Monitoring Metrics */}
      <div className="container mx-auto p-6">
        <h2 className="text-2xl font-bold mb-4">Server Monitoring Dashboard</h2>
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {metrics.map((metric, index) => (
            <div key={index} className="bg-white shadow-md p-4 rounded-lg">
              <h3 className="text-lg font-semibold">Server: {metric.server_id}</h3>
              <p>CPU Usage: {metric.cpu_usage}%</p>
              <p>Memory Usage: {metric.memory_usage}%</p>
              <p>Disk Usage: {metric.disk_usage}%</p>
              <p>Uptime: {Math.round(metric.uptime / 3600)} hours</p>
              <p>Logs: {JSON.parse(metric.logs).slice(0, 5).join(", ")}</p>
            </div>
          ))}
        </div>
      </div>

      {/* Widgets Section */}
      <div style={{ display: "flex", flexWrap: "wrap", gap: "2rem", marginTop: "2rem" }}>
        {/* Monitoring Widget */}
        <MonitoringWidget />

        {/* Machine Learning Widget */}
        <MLWidget />

        {/* Error Rates Widget */}
        <div
          style={{
            flex: "1",
            padding: "1.5rem",
            backgroundColor: darkMode ? "#2d3748" : "#fff",
            borderRadius: "8px",
            boxShadow: "0 2px 8px rgba(0, 0, 0, 0.1)",
          }}
        >
          <h3>Error Rates</h3>
          <p
            style={{
              fontSize: "1.5rem",
              fontWeight: "bold",
              color: darkMode ? "#f1c40f" : "#e74c3c",
            }}
          >
            {errorRate}
          </p>
        </div>

        {/* Server Logs Widget */}
        <div
          style={{
            flex: "1",
            padding: "1.5rem",
            backgroundColor: darkMode ? "#2d3748" : "#fff",
            borderRadius: "8px",
            boxShadow: "0 2px 8px rgba(0, 0, 0, 0.1)",
            overflowY: "auto",
            maxHeight: "200px",
          }}
        >
          <h3>Server Logs</h3>
          <ul style={{ listStyle: "none", padding: "0", margin: "0" }}>
            {serverLogs.map((log, index) => (
              <li key={index} style={{ marginBottom: "0.5rem" }}>
                - {log}
              </li>
            ))}
          </ul>
        </div>

        {/* Automated Resolution Widget */}
        <div
          style={{
            flex: "1",
            padding: "1.5rem",
            backgroundColor: darkMode ? "#2d3748" : "#fff",
            borderRadius: "8px",
            boxShadow: "0 2px 8px rgba(0, 0, 0, 0.1)",
            textAlign: "center",
          }}
        >
          <h3>Automated Resolution</h3>
          <button
            onClick={handleAutomateResolution}
            style={{
              padding: "0.75rem 1.5rem",
              backgroundColor: "#4caf50",
              color: "#fff",
              border: "none",
              borderRadius: "5px",
              cursor: "pointer",
              marginTop: "1rem",
            }}
          >
            Trigger Automation
          </button>
          <p style={{ marginTop: "1rem", fontSize: "0.9rem", color: darkMode ? "#f8fafc" : "#555" }}>
            This will automatically resolve common server issues, including:
          </p>
          <ul
            style={{
              listStyle: "disc",
              textAlign: "left",
              margin: "0.5rem 0 0 1rem",
              color: darkMode ? "#f8fafc" : "#555",
              fontSize: "0.9rem",
            }}
          >
            <li>Clearing cache</li>
            <li>Restarting affected services</li>
            <li>Freeing up memory</li>
            <li>Updating configuration files</li>
          </ul>
        </div>
      </div>
    </div>
  );
};

export default AdminDashboard;
